 static class PdfWriter{PdfDocument doc=new PdfDocument();PdfDocument.Page page;Canvas c;Paint p=new Paint(3);int number;float y;PdfWriter(){p.setColor(Color.BLACK);p.setTextSize(11);next();}void next(){if(page!=null)doc.finishPage(page);page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++number).create());c=page.getCanvas();y=40;}void line(String value){for(String text:String.valueOf(value).split("\n",-1)){if(text.isEmpty()){y+=16;continue;}while(!text.isEmpty()){if(y>800)next();int n=p.breakText(text,true,515,null);if(n<1)n=1;c.drawText(text.substring(0,n),40,y,p);y+=16;text=text.substring(n);}}}void image(byte[] bytes){if(bytes==null)return;Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(b==null)return;float h=Math.min(250,515f*b.getHeight()/b.getWidth()),w=h*b.getWidth()/b.getHeight();if(y+h>800)next();c.drawBitmap(b,null,new RectF(40,y,40+w,y+h),p);y+=h+16;b.recycle();}byte[] finish()throws Exception{doc.finishPage(page);page=null;ByteArrayOutputStream out=new ByteArrayOutputStream();doc.writeTo(out);return out.toByteArray();}void close(){if(page!=null)doc.finishPage(page);doc.close();}}
